import numpy as np, random, ot

def sort_match(a_points, b_points):
    src_idx=np.argsort(a_points[:,0])
    tgt_idx=np.argsort(b_points[:,0])
    return src_idx, tgt_idx

def test(trials=200,n=100):
    for seed in range(trials):
        random.seed(seed); np.random.seed(seed)
        a=ot.utils.unif(n); b=ot.utils.unif(n)
        src=np.random.rand(n,2);
        tgt=np.random.rand(n,2);
        M=ot.dist(src, tgt)
        row_ind, col_ind = sort_match(src, tgt)
        G=np.zeros_like(M)
        G[row_ind, col_ind]=a
        G_ref=ot.lp.emd(a,b,M,check_marginals=False)
        if not np.allclose(G, G_ref):
            return False, seed
    return True, None

print(test())
